const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
    // 1. Geometry & Time Definitions
    // Approximate bounding box for Bradwell Bay Wilderness, Apalachicola National Forest, Florida
    var wilderness = ee.Geometry.Polygon([[
        [-84.6, 30.2],
        [-84.4, 30.2],
        [-84.4, 30.0],
        [-84.6, 30.0],
        [-84.6, 30.2]
    ]]);

    var earlyStart = '2004-04-01';
    var earlyEnd = '2004-04-10';
    var lateStart = '2004-04-20';
    var lateEnd = '2004-04-30';

    // 2. Data Acquisition & Processing Function
    function getBurnedArea(startDate, endDate) {
        // Landsat 5 Surface Reflectance collection
        var col = ee.ImageCollection('LANDSAT/LT05/C02/T1_L2')
            .filterBounds(wilderness)
            .filterDate(startDate, endDate);

        var count = col.size();
        var countInfo = count.getInfo();

        if (countInfo === 0) {
            return {area: null, pixels: 0, imgCount: 0};
        }

        // Function to mask clouds and shadows using QA_PIXEL
        function maskClouds(image) {
            var qa = image.select('QA_PIXEL');
            var cloudShadowBitMask = 1 << 3;
            var cloudsBitMask = 1 << 5;
            var mask = qa.bitwiseAnd(cloudShadowBitMask).eq(0)
                .and(qa.bitwiseAnd(cloudsBitMask).eq(0));
            return image.updateMask(mask);
        }

        // Apply cloud mask and compute NBR
        var colMasked = col.map(maskClouds);

        // Compute NBR: (B4 - B7) / (B4 + B7) for Landsat 5
        // Scale reflectance: 0.0000275 * DN - 0.2
        var nbrCol = colMasked.map(function(image) {
            var nir = image.select('SR_B4').multiply(0.0000275).add(-0.2);
            var swir = image.select('SR_B7').multiply(0.0000275).add(-0.2);
            var nbr = nir.subtract(swir).divide(nir.add(swir)).rename('NBR');
            return nbr.copyProperties(image, ['system:time_start']);
        });

        // Median composite
        var medianNbr = nbrCol.median();

        // Threshold for burn scars (NBR < 0.2)
        var burned = medianNbr.lt(0.2);

        // Count valid pixels in the burned mask
        var pixelCount = burned.reduceRegion({
            reducer: ee.Reducer.count(),
            geometry: wilderness,
            scale: 1000,  // Use 1000m scale for efficiency
            maxPixels: 1e9
        }).get('NBR').getInfo();

        if (pixelCount === 0) {
            return {area: null, pixels: 0, imgCount: countInfo};
        }

        // Calculate burned area in square meters
        var pixelArea = burned.multiply(ee.Image.pixelArea());
        var areaStats = pixelArea.reduceRegion({
            reducer: ee.Reducer.sum(),
            geometry: wilderness,
            scale: 1000,
            maxPixels: 1e9
        });

        var area = areaStats.get('NBR').getInfo();

        return {area: area, pixels: pixelCount, imgCount: countInfo};
    }

    // 3. Get Burned Areas for Both Periods
    var earlyResult = getBurnedArea(earlyStart, earlyEnd);
    var lateResult = getBurnedArea(lateStart, lateEnd);

    // 4. Validation & Output
    console.log(`Early April Images: ${earlyResult.imgCount} (Valid Pixels: ${earlyResult.pixels})`);
    console.log(`Late April Images: ${lateResult.imgCount} (Valid Pixels: ${lateResult.pixels})`);

    // Case C1: No images found
    if (earlyResult.imgCount === 0 || lateResult.imgCount === 0) {
        console.log('<answer>C1</answer>');
        return;
    }

    // Case C2: No valid pixels after processing
    if (earlyResult.pixels === 0 || lateResult.pixels === 0) {
        console.log('<answer>C2</answer>');
        return;
    }

    // Case C3: Calculation failure (null or invalid values)
    if (earlyResult.area === null || lateResult.area === null || 
        isNaN(earlyResult.area) || isNaN(lateResult.area)) {
        console.log('<answer>C3</answer>');
        return;
    }

    console.log(`Early April Burned Area: ${earlyResult.area.toFixed(0)} m²`);
    console.log(`Late April Burned Area: ${lateResult.area.toFixed(0)} m²`);

    // 5. Compare Areas and Determine Answer
    if (lateResult.area > earlyResult.area) {
        console.log('<answer>A</answer>');
    } else {
        console.log('<answer>B</answer>');
    }
}

async function initEE() {
    await new Promise((resolve, reject) => {
        ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
    });
    await new Promise((resolve, reject) => {
        ee.initialize(null, null, resolve, reject);
    });
    await runAnalysis();
}

initEE();
